    protected string mUserName = "";
    protected string mUserInitial = "\u7BA1";
    protected string mUserAvatarUrl = "";

    private object MDecodeCookie(string typeName, string cookieValue)
    {
        Type cookType = typeof(LearnSite.Common.CookieHelp).Assembly.GetType(typeName);
        if (cookType == null) return null;
        object model = Activator.CreateInstance(cookType);
        System.Reflection.MethodInfo toModel = cookType.GetMethod("ToModel", mFlags);
        if (toModel != null) toModel.Invoke(model, new object[] { cookieValue });
        return model;
    }

    private string MGetProp(object model, string propName)
    {
        if (model == null) return "";
        System.Reflection.PropertyInfo prop = model.GetType().GetProperty(propName);
        if (prop == null) return "";
        object val = prop.GetValue(model, null);
        return val != null ? val.ToString() : "";
    }

    private void LoadMasterUserInfo()
    {
        int hid = 0;
        // Manager cookie
        try
        {
            HttpCookie mc = Request.Cookies[LearnSite.Common.CookieHelp.mngCookieNname];
            if (mc != null && !string.IsNullOrEmpty(mc.Value))
            {
                object m = MDecodeCookie("LearnSite.Model.MngCook", mc.Value);
                string name = MGetProp(m, "Hname");
                if (!string.IsNullOrEmpty(name))
                {
                    try { if (name.Contains("%")) name = Server.UrlDecode(name); } catch { }
                    mUserName = name; mUserInitial = name.Substring(0, 1);
                }
                string sid = MGetProp(m, "Hid");
                if (!string.IsNullOrEmpty(sid)) int.TryParse(sid, out hid);
            }
        }
        catch { }
        // Teacher cookie fallback
        if (string.IsNullOrEmpty(mUserName))
        {
            try
            {
                HttpCookie tc = Request.Cookies[LearnSite.Common.CookieHelp.teaCookieNname];
                if (tc != null && !string.IsNullOrEmpty(tc.Value))
                {
                    object t = MDecodeCookie("LearnSite.Model.TeaCook", tc.Value);
                    string name = MGetProp(t, "Hname");
                    if (!string.IsNullOrEmpty(name))
                    {
                        try { if (name.Contains("%")) name = Server.UrlDecode(name); } catch { }
                        mUserName = name; mUserInitial = name.Substring(0, 1);
                    }
                    if (hid <= 0)
                    {
                        string sid = MGetProp(t, "Hid");
                        if (!string.IsNullOrEmpty(sid)) int.TryParse(sid, out hid);
                    }
                }
            }
            catch { }
        }
        // Find avatar file on disk (no DB needed)
        if (hid > 0)
        {
            string[] exts = { ".png", ".jpg", ".jpeg", ".gif", ".webp" };
            foreach (string ext in exts)
            {
                string fp = Server.MapPath("~/images/avatars/" + hid + ext);
                if (System.IO.File.Exists(fp))
                {
                    mUserAvatarUrl = ResolveUrl("~/images/avatars/" + hid + ext) + "?t=" + System.IO.File.GetLastWriteTime(fp).Ticks;
                    break;
                }
            }
        }
    }

    protected void Page_Load(object sender, EventArgs e)
    {
        Page.Title = GetSiteTitle() + " - \u7BA1\u7406\u540E\u53F0";
        LitFavicon.Text = GetFaviconLinkTag();
        LoadMasterUserInfo();
    }

    protected void BtnMasterLogout_Click(object sender, EventArgs e)
    {
        try
        {
            HttpCookie mngCookie = new HttpCookie(LearnSite.Common.CookieHelp.mngCookieNname);
            mngCookie.Expires = DateTime.Now.AddDays(-1);
            Response.Cookies.Add(mngCookie);
        }
        catch { }

        try
        {
            HttpCookie teaCookie = new HttpCookie(LearnSite.Common.CookieHelp.teaCookieNname);
            teaCookie.Expires = DateTime.Now.AddDays(-1);
            Response.Cookies.Add(teaCookie);
        }
        catch { }

        try { Session.Abandon(); }
        catch { }

        Response.Redirect("~/manager/login.aspx");
    }

